#include <stdio.h>
int main(){
    double eta=0.05, beta=0.9, g=-0.2, v0=0.1, w=0.5, lam=0.01;
    double v1 = beta*v0 + eta*g;
    double w1 = w - v1;
    double delta = eta*lam*w1;
    double w2 = w1 - delta;
    printf("v1 = %.5f\n", v1);
    printf("w1 = %.5f\n", w1);
    printf("w2 = %.5f\n", w2);
    return 0;
}
